SELECT (DATE_TRUNC('DAY', "EVENT_AT")) AS "TIME_BUCKET", COUNT(DISTINCT CLIENT_TYPE) AS "SEC_CLIENT_TYPE_SPREAD" FROM (SELECT "EVENT_ID" AS EVENT_ID, (TRY_CAST("EVENT_TIMESTAMP" AS TIMESTAMP)) AS EVENT_AT, "EVENT_TYPE" AS EVENT_TYPE, "USER_NAME" AS USER_NAME, "CLIENT_IP" AS CLIENT_IP, "REPORTED_CLIENT_TYPE" AS CLIENT_TYPE, "REPORTED_CLIENT_VERSION" AS CLIENT_VERSION, "FIRST_AUTHENTICATION_FACTOR" AS FIRST_AUTH_FACTOR, "SECOND_AUTHENTICATION_FACTOR" AS SECOND_AUTH_FACTOR, "IS_SUCCESS" AS IS_SUCCESS, "ERROR_CODE" AS ERROR_CODE, "ERROR_MESSAGE" AS ERROR_MESSAGE FROM login_history) AS base GROUP BY (DATE_TRUNC('DAY', "EVENT_AT")) ORDER BY "SEC_CLIENT_TYPE_SPREAD" DESC, "TIME_BUCKET" LIMIT 100
